fn newell_area(pts: &[Pnt3], normal: Vec3) -> f64 {
    if pts.len() < 3 {
        return 0.0;
    }
    let mut cx = 0.0;
    let mut cy = 0.0;
    let mut cz = 0.0;
    for i in 0..pts.len() {
        let j = (i + 1) % pts.len();
        cx += pts[i].y * pts[j].z - pts[i].z * pts[j].y;
        cy += pts[i].z * pts[j].x - pts[i].x * pts[j].z;
        cz += pts[i].x * pts[j].y - pts[i].y * pts[j].x;
    }
    let area_vec = Vec3::new(cx, cy, cz);
    0.5 * area_vec.dot(normal).abs()
}

