/// 🟰 The 16-point Gauss–Legendre rule on [-1, 1] (nodes by Newton on `P₁₆`, weights `2 / ((1 − x²) P₁₆′(x)²)`) — exact for
/// polynomials of degree ≤ 31, machine-precise on an analytic edge's smooth integrand over a span of at most π/8.
// 🚫️async: E1 pure codec/computation helper (file verified I/O-free, consumed via Fn-bound combinator/Display) — see R9
fn gauss_legendre_16() -> &'static [(f64, f64); 16] {
    static RULE: std::sync::OnceLock<[(f64, f64); 16]> = std::sync::OnceLock::new();
    RULE.get_or_init(|| {
        let n = 16;
        std::array::from_fn(|index| {
            let mut x = (std::f64::consts::PI * (index as f64 + 0.75) / (n as f64 + 0.5)).cos();
            let mut derivative = 0.0;
            for _ in 0..100 {
                let (mut p0, mut p1) = (1.0, x);
                for k in 2..=n {
                    (p0, p1) = (p1, ((2 * k - 1) as f64 * x * p1 - (k - 1) as f64 * p0) / k as f64);
                }
                derivative = n as f64 * (x * p1 - p0) / (x * x - 1.0);
                let step = p1 / derivative;
                x -= step;
                if step.abs() < 1e-16 {
                    break;
                }
            }
            (x, 2.0 / ((1.0 - x * x) * derivative * derivative))
        })
    })
}

/// 🟰 Exact region integrals of one planar loop by Green's theorem over its trimmed edge curves — `(A, ∫u dA, ∫v dA)` in the
/// plane frame (u along `frame.x`, v along `frame.y`), signed by the loop's winding about `frame.z`: `A = ½∮(u dv − v du)`,
/// `∫u dA = ½∮u² dv`, `∫v dA = −½∮v² du`, each edge integrated with [`gauss_legendre_16`] over spans of at most π/8 (arcs) or 32
/// spans (NURBS). A curved boundary (a cylinder's cap, a plate's round hole) is never polygonised, so a planar face's area and
/// its divergence-theorem contribution are exact and independent of where the solid sits.
// 🚫️async: E1 pure codec/computation helper (file verified I/O-free, consumed via Fn-bound combinator/Display) — see R9
fn planar_loop_region_integrals(body: &Body, loop_id: crate::standards::v1::subsets::brep::schema::snapshot::arena::LoopId, frame: &crate::standards::v1::subsets::brep::schema::snapshot::vector::matrix::Frame3) -> Result<(f64, f64, f64), KernelError> {
    let rule = gauss_legendre_16();
    let (mut area, mut first_u, mut first_v) = (0.0, 0.0, 0.0);
    for coedge in body.loop_coedges(loop_id) {
        let co = body.coedges.get(coedge).ok_or_else(|| KernelError::MissingEntity("coedge".into()))?;
        let edge = body.edges.get(co.edge).ok_or_else(|| KernelError::MissingEntity("edge".into()))?;
        let curve = body.curves3.get(edge.curve).ok_or_else(|| KernelError::MissingEntity("curve".into()))?;
        let (t0, t1) = if co.forward { edge.range } else { (edge.range.1, edge.range.0) };
        let spans = match curve {
            Curve3::Line { .. } => 1,
            Curve3::Circle { .. } | Curve3::Ellipse { .. } => ((t1 - t0).abs() / (std::f64::consts::PI / 8.0)).ceil().max(1.0) as usize,
            Curve3::Nurbs { .. } => 32,
        };
        for span in 0..spans {
            let a = t0 + (t1 - t0) * span as f64 / spans as f64;
            let b = t0 + (t1 - t0) * (span + 1) as f64 / spans as f64;
            let (mid, half) = ((a + b) / 2.0, (b - a) / 2.0);
            for &(node, weight) in rule {
                let t = mid + half * node;
                let offset = curve.eval(t) - frame.origin;
                let tangent = curve.d1(t);
                let (u, v, du, dv) = (offset.dot(frame.x), offset.dot(frame.y), tangent.dot(frame.x), tangent.dot(frame.y));
                let w = weight * half;
                area += w * 0.5 * (u * dv - v * du);
                first_u += w * 0.5 * u * u * dv;
                first_v -= w * 0.5 * v * v * du;
            }
        }
    }
    Ok((area, first_u, first_v))
}

