/// ⚖️ LAW: mass properties do not depend on where a solid sits. A planar face bounded by circles (a cylinder's or a cone's cap, a
/// plate's round hole) is integrated by Green's theorem over its exact edge curves: the cap's area is πr², and translating a
/// cylinder or a cone leaves its volume unchanged and moves its centre of mass by exactly the offset (the caps used to be
/// polygonised — a translated cone lost 1.3e-4 of its volume, its centre of mass sat 4e-3 off).
#[test]
fn mass_properties_are_exact_and_independent_of_placement() {
    use crate::standards::v1::subsets::brep::schema::engine::{Brep, BrepKernel};
    let mut kernel = Brep::new();
    let shapes: [(&str, f64, [f64; 3]); 2] = [("cylinder", PI * 0.25 * 4.0, [0.0, 0.0, 2.0]), ("cone", PI * 3.0 / 3.0, [0.0, 0.0, 0.75])];
    let mut report = Vec::new();
    for (kind, volume, centre) in shapes {
        for offset in [[0.0, 0.0, 0.0], [100.0, -50.0, 30.0], [-7.5, 3.25, -12.0]] {
            let local = if kind == "cylinder" { kernel.cylinder_prim(0.5, 4.0) } else { kernel.cone_prim(1.0, 3.0) }.expect("primitive");
            let placed = kernel.translate(&local, offset).expect("translate");
            let measured = kernel.volume(&placed).expect("volume");
            let got = kernel.center_of_mass(&placed).expect("centre of mass");
            let centre_error = (0..3).map(|axis| (got[axis] - centre[axis] - offset[axis]).abs()).fold(0.0, f64::max);
            report.push(format!("{kind} at {offset:?}: volume rel error {:.3e}, centre error {centre_error:.3e}", (measured - volume).abs() / volume));
            assert!((measured - volume).abs() <= 1e-9 * volume && centre_error <= 1e-9, "{report:#?}");
        }
    }
    let cylinder = kernel.cylinder_prim(0.5, 4.0).expect("cylinder");
    let areas: Vec<f64> = kernel.deconstruct(&cylinder).expect("topology").faces.iter().map(|face| kernel.area(face).expect("area")).collect();
    assert!(areas.iter().filter(|area| (**area - PI * 0.25).abs() <= 1e-12).count() == 2, "both caps are πr² exactly: {areas:?}");
}
